/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/bg.json — nu edita de mână */
__hubApps("bg",{"FreeDetect":{"line":"Искате да проверите дали текст изглежда написан или копиран от изкуствен интелект? 42 външни инструмента и генератор на цитати на едно място. Самото приложение нищо не засича.","detail":"Табло с 42 външни инструмента за откриване на ИИ/плагиатство и генератор на цитати (проверява ISBN). Локално не открива нищо; помага при проверка на източници.","tags":["каталог","цитати"]},"Arhiva-fara-frontiere":{"line":"Разглеждайте колекциите на Internet Archive без акаунт: търсене, страници на материали, преглед и любими. Неофициално; archive.org вижда вашия IP адрес и търсенията.","detail":"Неофициален браузър за колекциите на Internet Archive (търсене, страници на материали, преглед, любими и скорошни търсения, запазени локално), без акаунт. Не търси в Wayback Machine; archive.org получава вашия IP адрес и търсенията ви.","tags":["уеб архиви","източници"]},"AcademiSearch":{"line":"Едно търсене — научни статии от десетки отворени източници. Списъка можете да запазите за цитиране. Нужен е интернет; заявките отиват при тези услуги.","detail":"Академично метатърсене в 11 отворени API (OpenAlex, Crossref, arXiv и др.) плюс връзки към портали; експорт в BibTeX/RIS/CSV. Изисква интернет; заявките ви се изпращат към тези услуги.","tags":["литература","източници"]},"Surveyor":{"line":"Какви връзки има вашият сайт и кои от тях не работят? Изброява ги с котвите и пренасочванията. Външните не могат да се проверят надеждно. Само за ваши собствени сайтове.","detail":"Инвентаризира връзките на сайт (статичен HTML, интерфейс на английски), включително котви и пренасочвания. Външните не могат да бъдат потвърдени от браузъра (CORS); изпраща заявки; проверявайте само собствените си сайтове.","tags":["мъртви връзки","одит"]},"Trade-Free-Link-Guardian":{"line":"За вашия сайт на WordPress: намира повредените връзки и ги поправя без външни услуги. Променя реалното съдържание, затова първо направете резервно копие. Не е тествано на истински WordPress.","detail":"Плъгин за WordPress, който проверява връзките и детерминистично поправя развалените, без външна услуга. Променя реално съдържание: направете резервно копие. Не е тестван на истински WordPress.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Следете сайтовете си и вижте дали още отговарят. Работи само докато разделът е отворен. Страница с грешка също се брои за отговор. Интерфейсът е на английски.","detail":"Монитор за достъпност в браузъра: проверява дали сайтовете ви отговарят (не чете HTTP статус кода; 404/500 се броят за отговор). Само докато разделът е отворен. Интерфейс на английски.","tags":["мониторинг"]},"ScryVeil":{"line":"Проверете сигурността на домейн и получете текстов доклад, който можете да запазите. Някои проверки може да са непълни или да изискват ключ. Свързва се с услуги на трети страни; само за ваши домейни.","detail":"Диагностика на сигурността на домейн (DNS, RDAP, сертификати) с експортируем текстов отчет; проверките на заглавки и репутация често са блокирани или изискват ключ. Свързва се с трети страни; само за домейни, които притежавате.","tags":["OSINT","сигурност"]},"Vitrina":{"line":"Вмъкнете публична публикация от Facebook в сайта си без акаунт и копирайте готовия код. Неофициално; Meta вижда вашия IP, показването не е гарантирано.","detail":"Вгражда публични Facebook страници/публикации чрез плъгините на Meta, неофициално; копира кода за вграждане. „Без акаунт“ не означава „без проследяване“: Meta вижда вашия IP адрес; показването не е гарантирано.","tags":["следене на емисии"]},"Threads-fara-cont":{"line":"Четете публични публикации от Threads без акаунт и ги запазвайте като текст. Неофициално; Meta вижда вашия IP, понякога е нужен посредник.","detail":"Показва публични публикации в Threads чрез вграждането на Meta, без акаунт; по избор локално запазване, експорт в .txt. Meta вижда вашия IP адрес; може да изисква CORS прокси. Неофициално.","tags":["следене на емисии"]},"X-fara-cont":{"line":"Достъп до публични профили и публикации в X без акаунт по няколко начина: пряка връзка, архив, търсене или Nitter. Не чете съдържанието; изпраща връзката до archive.org.","detail":"Генерира пътища за достъп без акаунт до публични профили и публикации в X: пряка връзка, архив в Wayback, търсене, Nitter. Не чете съдържанието; изпраща потребителското име/връзката към archive.org.","tags":["следене на емисии"]},"Arhiva-LinkedIn":{"line":"Пазете на едно място бележки за публикации от LinkedIn, които сте поставили сами, и ги изнасяйте като текст. Галерията използва официално вграждане, затова се свързва с LinkedIn. Неофициално.","detail":"Архив на бележки към ръчно поставени публикации от LinkedIn (внос от CSV, експорт в Markdown) + галерия чрез официалното вграждане на LinkedIn (свързва се с LinkedIn). Неофициално.","tags":["архивиране"]},"Cadraj":{"line":"Събирайте клипове от TikTok ръчно, групирани по автор, и ги гледайте в официалния плейър. Можете да отбелязвате вече гледаните.","detail":"Ръчна колекция от клипове в TikTok по автор, възпроизвеждани чрез официалния плейър; маркер „видяно“.","tags":["следене на емисии"]},"FASCICUL":{"line":"Превръща телефоните в стаята в обща дъска на видеопроектор: рисунки, бележки, изображения, лазерна показалка и камера на живо. Тествано на компютър; на реални телефони още не е потвърдено.","detail":"Телефони ↔ видеопроектор: обща дъска с рисуване, бележки, изображения, лазерна показалка и камера на живо, в един файл. Директна WebRTC връзка в локалната мрежа, без сървър на трета страна; по избор релей на телефона с точка за достъп (Android/Termux). Тестван в Chromium; още не е проверен на истински телефони.","tags":["сътрудничество"]},"INDICATIV":{"line":"Подгответе се за радиолюбителския изпит на ANCOM без интернет: 723 въпроса с разпределено повторение. Неофициално; банката с въпроси е проверена само частично.","detail":"Офлайн, неофициален тренажор за изпита за радиолюбители на ANCOM (723 въпроса, интервално повторение, търсене в базата с въпроси). Не е материал на ANCOM; базата с въпроси е само частично проверена.","tags":["изпит","радио"]},"ETER":{"line":"Учете радиолюбителство в енциклопедия: морзова азбука, тренажор, калкулатори за антени и търсене във всичкото съдържание.","detail":"Енциклопедия за радиолюбители: морзов код, тренажор по метода на Кох, калкулатори за антени, глобално търсене.","tags":["радио","енциклопедия"]},"ATINGERE":{"line":"Превръща книга в шрифт на Брайл с вибрации на сензорния екран за глухослепи или в аудиокнига за слепи. Не е проверено с читатели на Брайл; има ограничения.","detail":"Преобразува книги в тактилен брайл или аудиокниги. Не е валидирано с читатели, за които това е роден начин на четене; вижте ограниченията в README.","tags":["достъпност"]},"Clopotel":{"line":"Спазвайте времето на конференция или работилница: сценичен таймер с вашата програма и сигнал, когато краят наближава. На румънски и английски.","detail":"Таймер за сцена с програма на изказванията (внос на текст/CSV) и предупредителен сигнал, RO/EN.","tags":["събития","MIT"]},"Monstrarium":{"line":"Планирайте работилница за правене на чудовища от рециклирани материали: приложението изчислява материалите и сесиите, предлага 50 чудовища със звук, 3D и образователна игра.","detail":"Планировчик за работилница за чудовища от рециклирани материали: сам изчислява материалите, график по серии, 50 оригинални чудовища със звуци, 3D и образователна игра.","tags":["работилница","MIT"]},"TranslateHub":{"line":"Избирайте измежду 22 инструмента за превод или превеждайте с ИИ със собствен ключ. Текстът, преведен с ИИ, отива към услугата на Anthropic.","detail":"Каталог от 22 инструмента за превод плюс ИИ преводач с ваш собствен ключ. Текстът за ИИ се изпраща до api.anthropic.com.","tags":["превод","ИИ"]},"DataWeave":{"line":"Отворете таблица и я разберете: статистика, графики, обобщени таблици и корелации. Данните ви остават на устройството.","detail":"Изследвайте CSV/TSV/JSON в един файл: таблица, статистики, графики, обобщаваща таблица и корелации; данните ви остават на вашето устройство.","tags":["данни"]},"MarkdownAtelier":{"line":"Пишете документи в Markdown и веднага виждайте как изглеждат, с прости формули; на 7 езика, без интернет. Текстовете остават в браузъра; запазвайте резервно копие.","detail":"Офлайн редактор на Markdown с преглед, GFM, подмножество на LaTeX (MathML), 7 езика, търсене и резервно копие в .json. Документите остават в браузъра.","tags":["писане"]},"RegexLab":{"line":"Изпробвайте регулярен израз и веднага вижте какво улавя; обяснения стъпка по стъпка, тестове и предупреждение, ако може да затрудни програмата.","detail":"Тестване на регулярни изрази в JavaScript с обяснения, тестове и предупреждение за ReDoS.","tags":["разработка"]},"SEOptimum":{"line":"Проверете доколко една уеб страница е готова за търсачките. 20 инструмента, включително анализ на страницата и преглед как ще изглежда в резултатите от търсенето.","detail":"20 SEO инструмента в браузъра: анализ на страницата, прегледи на SERP.","tags":["уеб"]},"SEVA":{"line":"Научете за съня, дневния ритъм на тялото, дишането и храненето в енциклопедия, която можете и да чуете. Само информация; не е медицински съвет.","detail":"Енциклопедия за доброто здраве: сън, циркаден ритъм, дишане, хранене; слушане с четене на глас. Информативно; не е медицински съвет.","tags":["здраве"]},"PULS":{"line":"Какво да правите, докато дойде линейката? Румънско ръководство за първа помощ с метроном за СЛР и по желание спешна карта. Клинично непроверено; звънете на 112.","detail":"Наръчник за първа помощ на румънски (СЛР с метроном, турникет), с търсене и по избор карта за спешни случаи. Съдържанието не е клинично валидирано от специалист; не заменя оторизиран курс. При спешен случай се обадете на 112.","tags":["здраве","спешни случаи"]},"VATRA":{"line":"Какво да правите, ако в природата свършат водата, огънят или подслонът? Енциклопедия за оцеляване без интернет, с търсене и бележки. Само за обучение; при спешност звънете на 112.","detail":"Офлайн енциклопедия за оцеляване (вода, огън, подслон, ориентиране), с търсене и бележки, запазени локално. Образователен материал, не заменя курс по първа помощ; при спешен случай се обадете на 112.","tags":["теренна работа"]},"Eclipsa-2027":{"line":"Вижте на карта без интернет къде и колко ще продължи пълното слънчево затъмнение на 2 август 2027 г., с градове и търсене на място. Стойностите са ориентировъчни; не гледайте Слънцето без филтър.","detail":"Офлайн карта на пълното слънчево затъмнение на 2 август 2027 г., с продължителности, покритие по градове и търсене на места. Ориентировъчни стойности; не гледайте към Слънцето без сертифицирани филтри.","tags":["астрономия"]},"orarium":{"line":"Колко е часът сега на Марс, на Луната или на астероид? Местно време на живо на 45 небесни тела. Приблизителен модел, не изисква интернет; не е за навигация.","detail":"Времето във всеки свят: местно време на живо на 45 тела (Луната, Марс, планети, спътници, астероиди), скорост на часовника спрямо Земята, разстояние и време за двупосочно предаване, конвертор на часови зони и карти на колонизацията. Ориентировъчен модел, офлайн; не за навигация. Включва полунощ и обед на всяко тяло, прозорци за предаване между Земята и тялото и връзка към TerRa.","tags":["астрономия","време"]},"TerRa":{"line":"3D глобус и карта, показващи деня и нощта на Земята, Луната и планетите. Позициите на спътниците може да изостават с около 3 месеца, докато не ги обновите онлайн.","detail":"3D глобус и карта: терминатор, Луна, планети. Сателитите използват остарял снимков запис (~3 месеца) офлайн; за текущи позиции обновете онлайн. Уникална връзка за всеки изглед; небето от всяко от 45-те тела на ORARIUM, свързани в двете посоки.","tags":["астрономия"]},"Horizons.BeyondLimits":{"line":"Пътувайте през историята на Вселената от Големия взрив до края през 91 забележителни момента. Бъдещето е научна спекулация, а не точна прогноза.","detail":"Карта на времевата линия от Големия взрив до края на Вселената: 91 събития, експорт в Markdown; бъдещето е спекулативно, не е валидирана прогноза.","tags":["космология"]},"Hyper4D":{"line":"Вижте как изглеждат четириизмерните фигури: въртете ги на екрана и ги разглеждайте от няколко ъгъла. Изображенията могат да се запазват.","detail":"4D геометрия в SVG: 3D сечения на 4D тела и политопи с 4D→3D→2D проекции, въртящи се в реално време, експорт в SVG.","tags":["математика"]},"ExploratoriiEco":{"line":"Теренно ръководство за любители на природата: от класификацията на живите същества и следите до биомите на Румъния, дневник на наблюденията, етика и спешни случаи.","detail":"Полево ръководство за натуралисти в 20 раздела: класификация на живота, следи и признаци, румънски биоми, калкулатори, дневник, етика, спешни случаи и речник.","tags":["природа"]},"FieldObserver":{"line":"Записвайте теренните си наблюдения; показанията от сензорите на телефона се добавят автоматично. Водите архив на излизанията си.","detail":"Дневник за полеви наблюдения със сензорите на телефона; архив, експорт в JSON/CSV.","tags":["теренна работа"]},"VietAR":{"line":"Снимайте или запишете растение или същество и получете представа сред 519 вида от Румъния. Може да греши; не яжте нищо на тази основа.","detail":"Ориентировъчно разпознаване на 519 румънски вида по изображение/звук; може да греши, не яжте растения или гъби въз основа на него. Моделите се изтеглят от трети страни; не е напълно офлайн.","tags":["биоразнообразие"]},"VOIAJOR":{"line":"Следете траекториите на Вояджър 1 и 2 от 1977 г. до милиард години напред, във всеки мащаб — от планетите до Млечния път. Ориентировъчен модел, не е за навигация.","detail":"Симулация на траекториите на Voyager 1 и 2 (от 1977 г. до над един милиард години): балистични дъги между реалните прелитания, екстраполация със слънчева гравитация и локална галактична динамика, хелиосферата, облакът на Оорт и 19 близки звезди със собствено движение.","tags":["Вояджър","симулация"]},"Nemurirea":{"line":"Открийте как старее тялото и какво казва науката за биологичните часовници и дълголетието, след това се изпитайте с тест. Не е медицински съвет.","detail":"Интерактивно есе за биологичните часовници и науката за дълголетието, с финален тест. С информативна цел, не е медицински съвет.","tags":["биология"]},"IncredibleCosmos":{"line":"Разположете планети и звезди така, че гравитацията им да насочи комета към целта. 108 нива, три трудности и до три звезди на ниво.","detail":"Гравитационна главоблъсканица: разположете планети и звезди така, че гравитацията им да насочи комета към целта; 108 нива в 12 категории, три степени на трудност, оценка от 1 до 3 звезди, с търсене.","tags":["игра","физика"]},"Cupa-Mondiala-2026":{"line":"Играйте на Световното първенство 2026 и следете развитието на въображаемия турнир. Резултатите са случайни, не са прогноза; неофициално.","detail":"Измислен, неофициален симулатор на Световното първенство през 2026 г.: случайни резултати, не прогнози; не е свързан с FIFA.","tags":["симулация","неофициално"]},"AGORA":{"line":"Как се появи еврото и какво означава за Румъния? 59 глави от Маастрихт до ЕЦБ и съвети за пътуващи. Неофициално.","detail":"Информативен атлас на еврозоната в 59 раздела: от Маастрихт и ЕЦБ до Румъния и еврото, плюс пътеводител за пътешественици. Неофициален, без правна стойност.","tags":["икономика","ЕС"]},"URME":{"line":"Подгответе се за поход по пътеката Колци–Алуниш в Бузъу: растения, кехлибар, вкаменелости, часове на изгрев и залез, екипировка. Картата не е за навигация.","detail":"Информативен, неофициален туристически пътеводител за Колци–Алуниш (растения, кехлибар, вкаменелости), с изгрев/залез и списък със снаряжение. Схематична карта, не за навигация; извличането от защитената територия е забранено.","tags":["природа","Бузъу"]},"Belot-fara-frontiere":{"line":"Запознайте се с белота и сродните игри в други страни, после играйте на масата: вие и партньор ИИ срещу двама противници ИИ. Включен е бележник за точките.","detail":"Атлас на семейството игри белот/бела/клавъясс/яс и игра за 4 играчи (вие и партньор с ИИ срещу двама противници с ИИ); румънският белот е приоритет; бележник за резултати.","tags":["карти","ИИ"]},"Scopone-fara-frontiere":{"line":"Научете как е възникнала скопоне, какви са правилата ѝ и как се променят от регион на регион, после играйте срещу компютър, който може да дава съвети.","detail":"Атлас на скопоне (15 листа: произход, правила, регионални разлики) и игра срещу локален ИИ (евристичен / Монте Карло), с подсказки; италиански или френски бои.","tags":["карти","ИИ"]},"Solitaire-fara-frontiere":{"line":"Разглеждайте и играйте пасианси като Klondike, FreeCell или Spider. Когато заседнете, поискайте подсказка или оставете компютъра да реши.","detail":"Атлас на игрите пасианс (Klondike, FreeCell, Spider и други) върху общ механизъм; „Подсказка“ от решавач с ограничение на възлите/времето и по избор автоматично решаване.","tags":["карти"]},"Sudoku-fara-frontiere":{"line":"136 вида судоку — от класическото до killer и 3D; разглеждайте и играйте. Помага с обяснения стъпка по стъпка и решава собствените ви главоблъсканици.","detail":"Атлас на 136 варианта на Судоку (класическо, killer, jigsaw, гръко-латинско, 3D и много други), с генератор с единствено решение, обяснено решаване стъпка по стъпка, 7 режима на игра и решавач.","tags":["главоблъсканици"]},"Domino-fara-frontiere":{"line":"Научете историята и правилата на доминото, после играйте на масата срещу един до трима противници, управлявани от компютъра. Ходът може да се върне.","detail":"Атлас на домино (произход, правила, приблизителни варианти) и маса за игра срещу 1–3 играчи с ИИ, с три нива; отмяна на ход.","tags":["домино","ИИ"]},"Mahjong-fara-frontiere":{"line":"Запознайте се с 8 вида маджонг; играйте пасианс или игра за четирима с трима прости противници, управлявани от компютъра. Работи без интернет.","detail":"Атлас на 8 варианта на маджонг, пасианс и маджонг за 4 играчи (riichi, Хонконг, Съчуан) срещу 3 прости евристични ИИ. Офлайн.","tags":["маджонг","ИИ"]},"Go-fara-frontiere":{"line":"Научете откъде идва го и как се играе, после опитайте силите си срещу компютър, който може да дава съвети. Не изпраща никакви данни през интернет.","detail":"Атлас на играта Го (18 листа: произход, правила, приблизителни варианти) и игра срещу локален ИИ (Монте Карло, не LLM), със SGF и подсказки; без мрежови заявки.","tags":["го","ИИ"]},"Zaruri-fara-frontiere":{"line":"26 игри със зарове, за които можете да четете, 12 от тях срещу компютъра; плюс симулатор на хвърляния с вероятности. Без пари; офлайн.","detail":"Атлас на 26 игри със зарове; 12 от тях се играят срещу дидактичен ИИ (не LLM), плюс симулатор NdM с точни вероятности. Не е хазартна игра; офлайн.","tags":["зарове"]},"Sah-fara-frontiere":{"line":"Над 700 разновидности на шаха за разглеждане и малък речник на термините; повечето можете да играете срещу компютъра. Работи без интернет.","detail":"706 записа за шахматни варианти (само част с проверен източник; някои са синтетични) и 299 термина в речника. Офлайн, с локален енджин за много варианти.","tags":["шахмат"]},"Dame-fara-frontiere":{"line":"Играйте 25 варианта на дамата срещу компютъра и запазвайте партията. Правилата на 16 от тях са само приблизителни и са отбелязани със ⚠.","detail":"25 варианта на дама, които се играят срещу дидактичен ИИ, с експорт на играта; 16 имат приблизителни правила (отбелязани с ⚠).","tags":["дама"]},"Table-fara-frontiere":{"line":"Табла, тавли, нарди и румънски разновидности на таблата; четете и играйте: 17 варианта срещу компютъра, с клавиатура или мишка.","detail":"Атлас за игра на семейството табла: табла, Tavli, Tavla, Narde, Gul Bara и румънски варианти; 17 варианта срещу обучаващ ИИ; игра с клавиатура.","tags":["табла"]},"Remi-fara-frontiere":{"line":"Запознайте се със семейството на ръми и играйте 19 варианта срещу компютъра със статистика. 8 езика; едри, лесно видими плочки или карти.","detail":"Атлас на семейството игри ръми: 19 варианта за игра срещу локален ИИ, със статистики; интерфейс на 8 езика, с големи плочки и карти.","tags":["ръми"]},"Carti-de-joc-fara-frontiere":{"line":"От пасианса и «Черен Петър» до покера: 17 игри с карти с обяснени правила, 8 от които можете да играете веднага.","detail":"Интерактивен атлас на игрите с карти, от пасианс и Старата мома до покер: 17 игри с листове с правила, 8 от тях за игра.","tags":["карти"]},"Undava":{"line":"Подгответе викторина или я играйте с приятели на един и същ телефон или компютър и преиграйте въпросите, на които сте отговорили грешно. Подобно на Kahoot, но без връзка.","detail":"Викторина в стила на Kahoot (без връзка с нея), в един файл: самостоятелно или с предаване на устройството на следващия играч, с повторение на грешките. Играта на живо е само в сървърното издание.","tags":["викторина","образование"]},"AI-Liber":{"line":"Разговаряйте с няколко асистенти с изкуствен интелект на едно място, някои работят на вашия компютър. Съобщенията отиват при избрания от вас доставчик; ИИ може да греши.","detail":"Чат с няколко доставчици на ИИ, включително локални (Ollama, WebLLM). Съобщенията отиват при доставчика, който изберете; отговорите на ИИ могат да са грешни.","tags":["ИИ"]},"LocalMind":{"line":"Чатете с малък асистент с изкуствен интелект, който работи направо във вашия браузър. Моделите се изтеглят от интернет веднъж; може да греши.","detail":"Чат с малки модели (Qwen3, LFM2), изпълнявани локално в браузъра (WebGPU). Моделите идват от Hugging Face; може да греши. Изисква локален сървър или публичната страница.","tags":["локален ИИ"]},"PromptVault":{"line":"Над 500 готови промпта за асистенти с ИИ; избирайте и отбелязвайте любими. Не запазва вашите собствени текстове.","detail":"Библиотека с над 500 подсказки с любими, не е мениджър за собствените ви подсказки.","tags":["промптове"]},"ARENA":{"line":"Накарайте два модела ИИ да отговарят на сляпо и гласувайте за по-добрия; класирането се пази на вашия компютър. Нужни са ви собствени ключове.","detail":"Слепи дуели между ИИ модели с локална Elo класация (експорт в CSV). Изисква собствени API ключове или локални сървъри; демонстрационните модели са симулирани.","tags":["оценка на ИИ"]},"Nexus-fara-frontiere":{"line":"Чатете с асистенти с ИИ от няколко доставчика; разговор с търсене и запазване. Нужни са интернет и собствени ключове, които се пазят нешифровани.","detail":"Клиент за ИИ чат със собствени API ключове (Anthropic, OpenAI, Google, съвместими с OpenAI), с търсене и експорт в Markdown; „агентите“ са подсказки. Изисква интернет; ключовете се съхраняват некриптирани.","tags":["агенти"]},"VoiceAtelier":{"line":"Чуйте как звучат стотици изкуствени гласове на десетки езици и научете как се прави аудиокнига. Онлайн образецът изпраща текста на външни услуги само с ваше разрешение.","detail":"Каталог от 427 невронни гласа (141 локала) и ръководство за аудиокниги. Онлайн мостра изпраща текста до релей и до Microsoft, само с ваше съгласие. Не е студио за TTS.","tags":["глас"]},"Trusa-fara-frontiere":{"line":"Комплект от 15 малки ежедневни инструмента: бележки, таблица, Markdown, пароли, финансов дневник и други. Няма официална връзка с YunoHost, който е вдъхновил категориите.","detail":"Набор от 15 малки модула, написани от нулата (бележки, електронна таблица, Markdown, пароли, финансов дневник и др.), вдъхновени от категориите приложения на YunoHost; без връзка с тях.","tags":["инструменти"]},"API-fara-frontiere":{"line":"Времето, снимки на NASA, позицията на МКС и десетки данни на живо на едно място. Нужен е интернет; не е тествано с реални услуги.","detail":"52 приспособления: 47 върху публични API (изисква интернет; при отваряне онлайн автоматично се свързва с Open-Meteo, NASA и ISS) и 5 локални помощни програми. Не е тестван срещу реални сървъри.","tags":["API"]},"OmniHost":{"line":"Голям пакет от над сто работни инструмента на едно място. Свързва се с четири външни услуги; подробности има в README.","detail":"Пакет за продуктивност (~4 MB, 141 модула). Свързва се с четири външни хоста; вижте README.","tags":["пакет"]},"VNTV":{"line":"Пускайте трейлърите на VideoNeat като непрекъснат телевизионен канал. Нужен е интернет; в режим P2P адресът ви е видим за другите зрители.","detail":"Трейлъри на VideoNeat като непрекъсната телевизионна програма, плюс добавка за Stremio. Изисква интернет (videoneat.com, videos.trom.tf); в P2P режим вашият IP адрес е видим за другите зрители.","tags":["медии","MIT"]},"OSATURA":{"line":"Оживете 2D рисунки: свържете ги със «скелет», задвижете ги и експортирайте анимацията в няколко формата. Алфа версия, засега малко тествана.","detail":"Енджин за 2D векторен риг и анимация на Rust (кости, IK, skinning, физика, автомати на състоянията) със студио в браузъра и експорт в SVG, PNG, GIF, Lottie и glTF. Нативна програма (команден ред + студио) и модул WebAssembly, не е единичен HTML файл; алфа, засега малко изпробван от потребители. Лицензи: библиотеки под MPL-2.0, CLI под AGPL-3.0-or-later.","tags":["анимация","MPL/AGPL"]},"OAZA":{"line":"340 безплатни уеб услуги, предимно без акаунт, в един каталог. Списъкът е проверен през юни 2026 г., но не автоматично.","detail":"Каталог от 340 безплатни уеб услуги на трети страни, обикновено използваеми без акаунт (не са проверени автоматично; проверено през юни 2026 г.).","tags":["услуги"]},"VaultCrypt":{"line":"Имате нещо, което да скриете от любопитни очи? Заключвайте файлове и текстове с парола направо в браузъра. Изгубена парола не може да се възстанови.","detail":"AES-256-GCM криптиране на файлове и текст в браузъра. Не е независимо одитирано; изгубена парола не може да бъде възстановена.","tags":["сигурност"]},"Akasha":{"line":"Тефтер, който работи офлайн, с етикети, търсене и връзки между страниците. За да не загубите нищо, изтегляйте свежо копие на файла.","detail":"Офлайн бележки в един файл, с тагове, търсене и връзки [[Заглавие]]; за да запазите данните си, изтегляте свеж екземпляр на файла (quine).","tags":["бележки"]},"CLEPSIDRA":{"line":"Часовник за обратно броене, будилник и графици за делнични и почивни дни. Следи празниците и собствените ви събития.","detail":"Обратен часовник, будилник, графици за делнични/почивни дни, празници, събития.","tags":["време"]},"Origami":{"line":"Учете сгъване на хартия стъпка по стъпка: означения, техники и илюстровани модели. Приложението помни докъде сте стигнали.","detail":"Ръководство по оригами: нотация, техники, модели стъпка по стъпка, с напредък, запазен локално.","tags":["изкуство"]},"Zicala":{"line":"Всеки ден по една румънска поговорка от колекция от 550. Можете да търсите и да запазвате любими; коментарите са писани с помощта на ИИ.","detail":"550 румънски пословици с пословица на деня, търсене и експорт/внос на любими; коментарите SWOT/TOWS са създадени с помощта на ИИ.","tags":["култура"]},"Limpezimea":{"line":"Четете научнофантастичния роман «Limpezimea» на седем езика. Съпътстващата хроника и критичното изследване са писани с помощта на ИИ (Claude).","detail":"Научнофантастичният роман „Limpezimea“ на 7 езика, издание за четене. Критичният апарат (хроника, студия) е написан с помощта на ИИ (Claude).","tags":["литература"]},"Nota-Zero":{"line":"Спекулативна фантастична история за теорията на струните на румънски, английски и френски, с бележки, обясняващи научните идеи. Художествена измислица, не академичен източник.","detail":"Спекулативен фантастичен разказ за теорията на струните, на румънски, английски и френски, с обяснителни научни бележки (художествена литература, не е академичен източник).","tags":["литература"]},"Pendulul":{"line":"Планета се люлее между три звезди и черна дупка: научнофантастичен роман в девет тома, написан от Alexio заедно с Claude. 3D симулация, четец със запазване за четене офлайн, EPUB и PDF.","detail":"Научнофантастичен роман в девет тома от Alexio, написан с Claude: една планета се люлее между три звезди и черна дупка. Включва 3D симулация и четец на книгата в един HTML файл, който можете да запазите и четете офлайн, плюс EPUB и PDF.","tags":["литература"]},"PrintreInteligente":{"line":"Влезте в интерактивен научнофантастичен роман с герои, вдъхновени от екипажа на «Артемис 2». Прегледите са измислени; преводът, гласът и функциите с ИИ използват външни услуги.","detail":"Интерактивен научнофантастичен роман, художествена литература с герои, вдъхновени от екипажа на Artemis 2; рецензиите са измислени. Преводът, онлайн гласът и функциите с ИИ използват външни услуги.","tags":["литература"]},"BorderlessMelodies":{"line":"Слушайте музика, която сама се композира, направо в браузъра. Може да се експортира като аудио; има таймер за заспиване.","detail":"Процедурна музика с Web Audio, с експорт на аудио и таймер за заспиване.","tags":["музика"]},"EcoulSpectral":{"line":"Вижте звука като изображение, изберете частта, която ви пречи, и я отделете или изтрийте. Включва намаляване на шума, засичане на звуци и запазване като WAV.","detail":"Локален редактор на спектрограми: отбележете област във времето и честотата и я изолирайте или премахнете; откриване на глас, намаляване на шума, експорт в WAV.","tags":["аудио"]},"Constelar":{"line":"Чатете с виртуални приятели, които помнят разговорите ви. По подразбиране отговарят по прости правила; истински ИИ само ако изберете доставчик, и тогава съобщенията ви отиват при него. Само за пълнолетни.","detail":"Разговорни спътници с локална памет. По подразбиране прост механизъм на правила; истински ИИ само ако изберете доставчик (съобщенията се изпращат до него). За възрастни; не замества терапия.","tags":["ИИ"]},"Tarot":{"line":"Открийте историята на таро, символите на картите и как се четат като културен феномен. Интерактивен курс със собствено темпо.","detail":"Интерактивен курс: историята, символите и тълкуването на картите, като културен феномен.","tags":["култура"]},"Numerologie":{"line":"Открийте нумерологията като символична традиция на четири нива, с упражнения, речник, дневник и калкулатор. Представено без научно потвърждение.","detail":"Интерактивен курс по нумерология като символна традиция: четири нива, упражнения, речник, дневник и калкулатор; представена без научна валидация.","tags":["култура"]},"PUNCTUM":{"line":"Образователен атлас на акупресурата и точковите терапии: над 400 точки на интерактивни карти, рутини за самопомощ с водени сесии, доказателства и безопасност. Не замества лекаря.","detail":"Образователен атлас на точковите терапии (акупунктура, акупресура, моксибустия, вендузи, аурикулотерапия, рефлексология и др.): 410 точки на 14 меридиана, 60 варианта с ниво на доказателства, SVG карти, състояния и рутини, курс, тест, флашкарти и лични проверки за безопасност.","tags":["здраве","доказателства"]},"Reiki":{"line":"Научете какво е рейки, духовна практика, и какво казват изследванията: не са намерени достатъчно доказателства за ефект отвъд отпускането. Не замества лекаря.","detail":"Курс по Рейки, духовна практика: прегледите откриват недостатъчни доказателства за какъвто и да е ефект отвъд релаксацията/плацебо; не замества лекар.","tags":["култура"]},"Bioenergoterapie":{"line":"Курс, който обяснява какво е биоенергийната терапия и откъде идва. Няма научни доказателства за лечебно действие на практиката; не замества лекаря.","detail":"Курс по биоенергийна терапия, практика без научни доказателства за лечебен ефект; не замества лекар.","tags":["култура"]},"CHIROMANTIA":{"line":"Интерактивен атлас на хиромантията: карта на дланта с линии, хълмове, пръсти и типове ръце, четена като културна традиция; с раздел за науката и критичното мислене. Без научно потвърждение.","detail":"Интерактивен атлас на хиромантията: SVG карта на дланта (лява/дясна), линии, хълмове, пръсти, типове ръце, отпечатъци, измервания 2D:4D, насочено четене, флашкарти, тест, сляп тест на Барнъм и симулатор на cold reading; всяко твърдение е с ниво на доказателства.","tags":["хиромантия","култура"]},"Radiestezie":{"line":"Преминете 18 нива за търсене на вода с пръчка, с речник, дневник на практиката и международни приложения. От самото начало посочва, че няма научно потвърждение.","detail":"Курс в 18 нива по радиестезия (лозоходство), с речник, дневник на практиката и международни приложения; от самото начало заявява, че няма научна валидация.","tags":["култура"]},"Inforenergetica":{"line":"Научете в структуриран курс какво твърди инфоенергетиката, нетрадиционна практика. Без научно потвърждение; не е медицински съвет.","detail":"Курс по инфоенергетика, нетрадиционна практика без научна валидация; не е медицински съвет.","tags":["култура"]},"ECLIPSA":{"line":"Научете в кой астрологичен дом на вашата натална карта попада затъмнението и за следващите 12 затъмнения. Изчислението е приблизително, тълкуването символично; без научно потвърждение.","detail":"В коя астрологична къща попада затъмнение върху натална карта, плюс следващите 12 затъмнения. Локално, приблизително астрономическо изчисление; символично тълкуване, астрологията няма научна валидация.","tags":["астрология"]},"Afrodisiace-fara-frontiere":{"line":"Четете за 22 храни и билки, традиционно свързвани с желанието, с ниво на доказателства за всяка. Културен справочник за възрастни, не е медицински съвет.","detail":"Културен пътеводител за 22 храни и растения, традиционно свързвани с желанието, с ниво на доказателства за всеки запис. Образователен, не е медицински съвет.","tags":["култура"]},"CalmWaves":{"line":"Фонова музика за релаксация и сън, създавана в движение. Не е медицинско изделие; разделът за изследвания не е проверен независимо. Консултирайте се с лекар (епилепсия).","detail":"Генеративна амбиентна музика за релаксация/сън. Не е медицинско изделие; разделът с изследвания не е независимо проверен. Потърсете медицински съвет (епилепсия).","tags":["аудио"]},"ASMR":{"line":"Съставете собствен успокояващ звуков пейзаж от слоеве атмосфера, звуци на докосване и бинаурални удари. Има таймер за заспиване и можете да споделите микса си.","detail":"Миксер за релаксиращи звуци, генерирани в реално време (Web Audio): амбиентни слоеве, звуци на докосване, бинаурални ритми и таймер за заспиване; микс, който може да се споделя.","tags":["аудио"]},"NOMIA":{"line":"Какъв би могъл да бъде първият контакт между хора, ИИ и други видове разум? 1001 въображаеми сценария; фантастика, не реалност. Работи и офлайн.","detail":"Концептуален симулатор на протоколи за контакт между човек, ИИ и NHI, 1001 записа, придружаващ антологията „Printre inteligențe“. Фантастика/спекулация, не проверени факти; офлайн PWA, RO/EN.","tags":["фантастика","спекулация","PWA"]},"ValeaPlopului1972":{"line":"Вижте случая с НЛО от 1972 г. отвън, отвътре и в симулация, реконструиран в 3D. Това е въображаема хипотеза, а не доказателство.","detail":"3D реконструкция на случая с НЛО във Валеа Плопулуй (1972): външност, симулация, въобразен интериор. Спекулативна, основана на непроверени публични източници, без съгласието на назованите лица; не е доказателство.","tags":["НЛО","3D","фантастика"]},"HoroScop":{"line":"Изчислете позициите на планетите за дата и място, после разгледайте наталната карта, аспектите и съвместимостта. Символична астрология, без научна основа. Работи офлайн.","detail":"Офлайн лична ефемерида: планетни позиции, изчислени в браузъра (намалена точност), натална карта, аспекти, синастрия. Символична астрология, без научна валидация; лиценз MIT.","tags":["астрология","ефемериди","офлайн"]},"Aurora":{"line":"Слушайте успокояващи тонове и леко пулсиращи звуци и следвайте водач за дишане. Само за релаксация, не е лечение. Работи без интернет.","detail":"Звуково убежище: тонове на чакрите, бинаурални ритми и ръководство за дишане, офлайн. Само за релаксация, не е медицина; честотите нямат научна валидация. Лиценз MIT; независим проект.","tags":["медитация","аудио","релаксация"]},"NumeroLogIA":{"line":"Научете какво казват нумерологията, китайската астрология БаЦзъ и биоритъмът за вашата дата на раждане, с обяснено всяко изчисление. Символична система, без научна основа.","detail":"Питагорейска/халдейска нумерология, BaZi и биоритъм на 7 езика, изчисления стъпка по стъпка, портрети, експортируеми като JSON; по избор ИИ оракул чрез ваш собствен модел. Символична система, без научна валидация; лиценз MIT.","tags":["нумерология","ИИ","офлайн"]},"FrequencyLaboratory":{"line":"Изпробвайте звуци, ефекти и тестове за слух в малка звукова лаборатория. «Терапевтичните» ефекти не са доказани; не замества лекаря. Работи офлайн.","detail":"Аудиолаборатория в браузъра (осцилатори, бинаурални, ефекти, анализатори, слухови тестове), офлайн. Само за информация: „терапевтичните“ предварителни настройки нямат доказан медицински ефект; не е медицинско изделие.","tags":["аудио","лаборатория","офлайн"]},"generator-frecvente":{"line":"Създавайте чисти тонове и пулсиращи двойки, слушайте познати предварителни настройки и приблизително проверете слуха си. Не е медицинско изделие. Работи офлайн.","detail":"Генератор на тонове в браузъра (бинаурални, секвенсор, EQ, ориентировъчен слухов тест, търсене на предварителни настройки), офлайн. Само за информация: настройките Solfeggio/Schumann нямат научна валидация; не е медицинско изделие.","tags":["аудио","генератор","офлайн"]},"ACORDAJ":{"line":"Разглеждайте над хиляда духовни курса и посвещавания с исторически контекст и критичен поглед. Не е свързан със сайта-източник и няма научно потвърждение. Работи офлайн.","detail":"Офлайн атлас на 1134 духовни курса/посвещения (списъкът от cursurispirituale.webnode.ro, без връзка с него), с исторически контекст и критичен подход; без научна валидация.","tags":["духовност","атлас","критично разграничаване"]},"Profund":{"line":"150 въпроса, които извеждат разговора отвъд малките приказки — между приятели или в семейството. Играйте на екрана или разпечатайте, с по желание таймер.","detail":"Игра със 150 въпроса за смислени разговори (RO/EN/FR), онлайн или на хартия, с играчи и по избор таймер; адаптирана от deepcards.org, оригиналите остават собственост на притежателите на правата (MIT само за кода и оригиналната част).","tags":["разговор","карти","trade-free"]},"Universul-Observabil":{"line":"Колко голяма е наблюдаемата Вселена? Сравнете три карти (линейна, плоска, в пространството) и правете космологични изчисления. Числата не са проверявани независимо.","detail":"Начална страница, която представя и сравнява 1D, 2D и 3D визуализациите на наблюдаемата Вселена, с офлайн космологичен калкулатор; данните и рекордите са от каталога от май 2026 г., не са независимо проверени. RO/EN.","tags":["астрономия","космология","визуализация"]},"Universul-Observabil-1D":{"line":"Пътувайте от нас до ръба на видимата Вселена покрай 112 галактики, подредени на една ос. Ироничен тон, закръглени стойности, образователна цел.","detail":"1D карта на наблюдаемата Вселена: 112 галактики върху радиална ос (време, разстояние, червено отместване), с таблица с данни и експорт в CSV. Образователна, с ироничен тон; закръглени стойности, рекорди към датата на каталога (май 2026 г.).","tags":["астрономия","космология","визуализация"]},"Universul-Observabil-2D":{"line":"Карта на галактиките в сатиричното издание «Плоската Земя»: шега е, Земята не е плоска. Приближавайте сред 111 галактики; разстоянията са приблизителни. Работи офлайн.","detail":"Интерактивна 2D карта на наблюдаемата вселена (111 галактики, логаритмична скала, данни от JWST) в сатиричното издание „Плоска Земя“: пародия, Земята не е плоска; разстоянията са приблизителни. RO/EN, офлайн.","tags":["астрономия","сатира","космология"]},"Universul-Observabil-3D":{"line":"Летете сред над 115 галактики на 3D карта с водени обиколки и мисии. Стойностите са приблизителни.","detail":"Интерактивна 3D карта (WebGL) на наблюдаемата вселена: 115+ галактики, 12 хоризонта, 30 обиколки, предизвикателства в ръководството, експорт в GLB/CSV/BibTeX. Приблизителни стойности; рекорди на JWST към май 2026 г.","tags":["астрономия","космология","3D"]},"QSO":{"line":"Водете дневник на радиовръзките на вашата радиолюбителска станция с време UTC, локатори и статистика. Неофициално; изчисленията са приблизителни.","detail":"Неофициален дневник на радиолюбителска станция: QSO с часовник в UTC, внос/експорт на ADIF 3.1, локатори на Maidenhead, проверка за дубли, статистики. Непълна таблица с префикси (не е DXCC); приблизителни изчисления.","tags":["радио","дневник"]},"Curatitor":{"line":"Вижте какво разкриват снимките и файловете ви (място, камера, автор) и премахнете тези данни преди изпращане. Не скрива лица или друго видимо съдържание.","detail":"Показва и премахва метаданните на файлове локално (GPS, камера, автор, софтуер) без прекодиране на пиксели или аудио, и проверява резултата отново. Не анонимизира съдържанието (лица, шум на сензора).","tags":["метаданни","поверителност"]},"Poteca":{"line":"Отворете следи, записани при поход или с колело, и вижте разстоянието, изкачването и профила на надморската височина. Можете да режете или съединявате. Без карта; изкачването е оценено.","detail":"Преглед и редактор за GPX/GeoJSON/KML/CSV трасета: статистики, профил на надморската височина, изрязване, свързване, опростяване, експорт. Без основна карта; изкачването/спускането са приблизителни оценки.","tags":["GPX","следи"]},"Orar":{"line":"Календар и седмичен планер с официалните румънски празници, с изглед по дни, седмици или месеци. Алармите звънят само докато страницата е отворена.","detail":"Календар и седмичен планировчик: изгледи за месец/седмица/ден/дневен ред, повторения по RFC 5545, часови зони, румънски официални празници, внос/експорт на .ics. Алармите звънят само докато разделът е отворен.","tags":["календар","време"]},"Alfabete":{"line":"Учете и упражнявайте морзова азбука, Брайл, фонетична азбука, флагова семафорна азбука и стари шифри, после разпечатайте страница. Старите шифри не пазят тайни.","detail":"Справочник, конвертор, тренажор и печатен лист за морзов код, брайл (степен 1), фонетични азбуки, семафор, Бодо, бройни системи и класически шифри. Класическите шифри не предлагат сигурност.","tags":["кодове","учене"]},"Fabrica":{"line":"Напишете курс като обикновен текст и го превърнете в страница с уроци, краен тест и сертификат за печат. Сертификатът няма официална стойност.","detail":"Фабрика за курсове и тестове: напишете курс в обикновен Markdown и го експортирайте като един самостоятелен HTML файл с локален напредък, краен тест и сертификат за печат (без акредитационна стойност).","tags":["курсове","създаване"]},"Bolta":{"line":"Какво беше небето над главата на всяко място и в който и да е ден между 1900 и 2100 г.? Слънце, Луна, планети и звезди, както и затъмнението от 2027 г. Стойностите са изчислени, неофициално. Работи офлайн.","detail":"Офлайн планетариум за всяко място и време между 1900 и 2100 г.: Слънце, Луна, планети, 1 627 звезди, съзвездия, събития и страница за затъмнението през 2027 г. Изчислени стойности, не са официални.","tags":["астрономия","планетариум"]},"BRAZDA":{"line":"Декодирайте Златния диск на Вояджър стъпка по стъпка, после кодирайте нов диск за сонда, която се изстрелва сега. Изображенията в първите стъпки са схематични, не са на NASA.","detail":"Декодер и кодер в 12 стъпки за Златния диск на Voyager: скорост, водородният часовник, картата на пулсарите, сигналът на изображение, калибриране с окръжността, декодиране ред по ред, цвят, собствен файл, приноси и кодиране на диск за 2026–2027 г.","tags":["Вояджър","сигнал"]},"Arbore":{"line":"Изградете семейно дърво с хора, семейства, времева линия и румънски калкулатор за родство. Данните остават само в този браузър, без синхронизиране.","detail":"Локална генеалогия: хора, семейства, внос/експорт на GEDCOM 5.5.1, SVG диаграми, времева линия, калкулатор на родство (само румънска терминология). Без синхронизация; данните остават в този браузър.","tags":["родословие","GEDCOM"]},"Gospodar":{"line":"Следете домашните пари: сметки, разходи, месечни бюджети и отчети. Акаунт не е нужен, но ако загубите паролата, губите данните. Не е финансов съвет.","detail":"Локален семеен бюджет: сметки, категории, транзакции, внос от CSV, месечни бюджети, отчети и калкулатори с прозрачни формули. Без акаунт и синхронизация; изгубена парола означава изгубени данни. Не е финансов съвет.","tags":["бюджет","лични финанси"]},"Decibel":{"line":"Измерете колко силен е шумът около вас и вижте от какви звуци се състои. Има и ориентировъчен тест за слух. Не е сертифициран уред; резултатите зависят от микрофона.","detail":"Шумомер, спектрален анализатор (1/3 октава, FFT) и ориентировъчен слухов тест. Не е сертифициран уред и няма правна или медицинска стойност; показанията зависят от микрофона и калибрирането.","tags":["звук","измерване"]},"Provenienta":{"line":"Имате изображение и искате да знаете кой го е подписал и какви редакции е декларирал? Проверете вградения цифров подпис. Експериментално, тествано само на примерни файлове.","detail":"Локална, експериментална проверка на C2PA / Content Credentials: показва кой е подписал и кои редакции са декларирани, и проверява подписа и връзката с байтовете на файла. Тествана само със синтетични файлове; без списък на доверие.","tags":["C2PA","произход"]},"Lexicon":{"line":"Донесете собствени речници и търсете думи дори когато пишете без диакритики или с грешки. Идва само с малък демонстрационен набор. Работи офлайн.","detail":"Офлайн речников енджин: донесете собствени речници (TSV/CSV, JSON, StarDict, dictd, XDXF) и търсете по представка, без значение на ударенията, размито или в пълен текст. Включеният набор (345 записа) е демонстрация, не е пълен речник.","tags":["речник","език"]},"VERIGA":{"line":"Намира повредени връзки и осиротели файлове в уебсайт или папка. Работи на Windows, macOS и Linux; нужно е малко познаване на компютъра.","detail":"Проверка на връзки (clean-room) за уебсайтове и локални папки, написана на Rust: команден ред, нативно настолно приложение (egui) и версия като единичен HTML файл. Проверява HTML и CSS връзки, пренасочвания, котви #fragment, осиротели файлове, robots.txt и sitemap. Windows, macOS и Linux; лиценз MIT.","tags":["проверка на връзки","MIT"]},"TEZAUR":{"line":"Асистент за дисертация, който пише само въз основа на вашите собствени книги и статии, с проверими цитати. Работи на вашия компютър; документите ви никога не го напускат. В разработка.","detail":"Локален изследователски асистент за писане на дисертация, написан на Rust, с отговори, обосновани с цитати: индексира вашите книги и статии (PDF, EPUB, DOCX, txt), извлича откъси и пише само от тях, с проверени цитати [n] и списък с литература. Работи на вашия компютър с локален модел (Ollama, Jan, LM Studio); документите ви никога не го напускат. Версия 0.x; лиценз MIT.","tags":["изследване","MIT"]},"LegatorOCR":{"line":"Сканирайте книга и получете чист PDF с коригирани страници и текст, в който може да се търси. Работи на Windows, macOS и Linux; сканираните ви файлове остават при вас.","detail":"Clean-room постпроцесор на Rust за сканирани книги: разделя двойни страници, изправя наклона, изрязва, задава полета, почиства и бинаризира, след което експортира PDF или изображения с търсим слой с OCR текст. Графично приложение (Windows, macOS, Linux) и команден ред, на 8 езика. Разпознаването на текст (OCR) изисква отделната програма Tesseract; всичко останало работи без нея. Версия 0.x; лиценз MIT.","tags":["сканиране","MIT"]},"Fenarium":{"line":"Атлас и работилница на субективните възприятия през всички сетива, започвайки с фосфенизма: курс с 13 модула, водени експерименти, визуален симулатор и лаборатория за А/Б самоексперименти с рандомизация. Образователно, не е медицинско изделие.","detail":"Атлас на фените (фосфени, последователни образи, звуци, наподобяващи тинитус, и др.), курс от 13 модула, лаборатория за самоекспериментиране; не е медицинско изделие.","tags":["възприятие","MIT"]},"MENSURA":{"line":"Измерете IQ, EQ, CQ, RQ, изпълнителните си функции и сетивата в 6 области с 18 теста, съставни индекси и 95% доверителни интервали. Предварителни норми, само ориентировъчно, не е диагноза.","detail":"18 теста в 6 области (IQ, EQ, CQ, RQ, изпълнителни функции, сетива), индекси с доверителни интервали, експорт/внос на JSON; временни норми.","tags":["тестове","MIT"]},"Cronosala":{"line":"Таймери за фитнес залата: почивка между серии, HIIT, Табата, EMOM, AMRAP, кръгове и метроном, плюс дневник на тренировките с кг и повторения.","detail":"Таймери за фитнес и дневник на тренировките в един HTML файл: адаптивна почивка между серии, Interval/HIIT, Tabata, EMOM, AMRAP, кръгови тренировки по станции, темпо, метроном, 4-седмична месечна програма, каталог с упражнения и QR кодове за уредите. Данните остават в браузъра; интерфейсът е на румънски.","tags":["спорт","време"]},"ScutSonor":{"line":"Силен звук и стробоскоп на фенерче при срещи с агресивни кучета, плюс ръководство за поведение. Помощ е, а не гарантирана защита.","detail":"Генерира сканиране от 2–8 kHz, експериментален ултразвук, сирена и тест на високоговорител, с лимитер, който запазва силата на звука, стробоскоп с фенерче (2,5 Hz), дневен режим и ръководство за безопасност. Един файл, без проследяване. Доказателствата, че звукът отблъсква кучета, са слаби.","tags":["безопасност","звук"]},"MIRAJ":{"line":"Как вижда ретината и как мозъкът изгражда образа: фовеа, сляпо петно, илюзии и тест, на три нива.","detail":"Интерактивно обяснение на зрението на три нива (начално, средно, напреднало): ретина, фовеа, сляпо петно, оптични илюзии, резюме и тест с 10 въпроса. Един файл, интерфейс на румънски и английски.","tags":["зрение","образование"]},"ANTROPOS":{"line":"Ориентировъчен научен профил, изчисляван локално: биологична възраст PhenoAge, глас, почерк, рисуване на часовник, личност по TIPI и време за реакция.","detail":"Образователен скринингов инструмент, не диагноза: биологична възраст по PhenoAge със защита за правдоподобност, анализ на гласа, графометрия на почерка, тестове с часовник и рисуване на човек, TIPI, тестове за реакция, печатен отчет и експорт в JSON. Данните остават в браузъра.","tags":["скрининг","биология"]},"DESCANTAR":{"line":"Гадаене на 41 зърна боб (метод 3×3, олтенски вариант) и 12 традиционни баяния като предмет на фолклорно проучване.","detail":"Румънско гадаене с боб по три метода (3×3 по книга, Олтения, три купчинки), четения по Глава, Сърце и Нозе, 12 традиционни заклинания, фаза на луната, брояч на рецитирането, генератор на заклинания, история и ръководство за копиране. Фолклорно съдържание, преведено на 8 езика с ИИ, не е прегледано от носители на езика.","tags":["фолклор","боб"]},"Index-fara-frontiere":{"line":"Каталог на еднофайлови HTML приложения: колекцията chiuta.github.io и външни източници, с търсене и етикети.","detail":"Осем проекта от колекцията на автора и осем външни ресурса, ясно отбелязани, с търсене на живо, тагове с щракване, превключвател RO/EN, тъмна/светла тема и запис, който каталогизира сам себе си. Без мрежови заявки. Статичен снимков запис от 5 юли 2026 г.","tags":["каталог","източници"]},"DECUPAJ":{"line":"Превърнете подкаст, аудио или видео във вертикални клипове със субтитри направо в браузъра, без акаунт и воден знак. Файловете ви никога не напускат устройството.","detail":"Вертикални рилси от подкаст (аудио или видео) в един HTML файл: изберете сегмента върху формата на вълната, получете предложения за моменти, локална транскрипция с Whisper, стилизирани субтитри, 4 съотношения (9:16, 4:5, 1:1, 16:9), опашка за експорт и MP4 чрез WebCodecs. Интерфейс на 8 езика.","tags":["reels","видео"]},"LECTOR":{"line":"Книги, четени на глас направо в браузъра: EPUB, DOCX, PDF, TXT или поставен текст, без акаунт и сървър. Текстът никога не напуска устройството ви.","detail":"Слушайте книги, четени на глас, от един HTML файл: EPUB, DOCX, PDF (с румънски OCR за сканирани), TXT; гласове на устройството или Piper ro_RO, подчертаване на изговорената дума, таймер за заспиване, глави, отметки, речник за произношение, локална библиотека и теми, подходящи за дислексия. Интерфейс на 8 езика.","tags":["аудио","книги"]},"FARFURIA":{"line":"Безплатен дигитален диетолог: персонализирани калории и макроси, 7-дневен хранителен план, дневник на храненето и следене на теглото. Не замества лекаря или диетолога.","detail":"Цифров диетолог в един HTML файл: цели за калории и макроси (Mifflin–St Jeor, ниво на активност, цел), 7-дневен план за хранене с филтри за диети и алергени, база данни с храни, хранителен дневник и проследяване на теглото. Правила за безопасност за непълнолетни, анамнеза за хранително разстройство и бъбречно заболяване. Интерфейс на 8 езика.","tags":["хранене","здраве"]},"VITALIS":{"line":"Личен спътник за здраве, дълголетие и биохакинг: девет стълба, подредени по доказателства, калкулатори, оценка на начина на живот и ежедневен ритуал. Не е медицински съвет.","detail":"Спътник за здраве и дълголетие в един HTML файл: девет стълба, подредени по доказателства, калкулатори (HOMA-IR, TyG, талия към ръст, Mifflin–St Jeor, зони на пулса, цикли на съня, протеини), таймер за гладуване, темпо за дишане, оценка 360 с радарна диаграма, референтни стойности на биомаркери и проследяване на дневен ритуал. Неофициален спътник на събитието BioHacking360. Интерфейс на 8 езика.","tags":["здраве","дълголетие"]},"REZONANTA":{"line":"Ръководство и инструменти за комуникация и медии: съобщение, канали, прессъобщение, интервю, яснота, план и криза.","detail":"Как да накарате хората да слушат, в един HTML файл: 12 принципа с практически тест, „къщата на посланието“ (30-секундна реч, публикация, кратка и говорима версия), препоръки за медийни канали, генератор на прессъобщение по метода на обърнатата пирамида, лист за интервю, анализатор на яснотата на текста, комуникационен план с експорт в текст/CSV и стъпките от първия час на една криза. Интерфейс на 8 езика.","tags":["комуникация","медии"]},"Claritas":{"line":"Универсално разширение за браузър за достъпност: корекция на контраста, режим за четене, четене на глас и проверка по WCAG. Без телеметрия, без мрежа, без акаунт.","detail":"Безплатно разширение за достъпност за браузъра: автоматична корекция на контраста (WCAG AA/AAA), теми с висок контраст, филтри за далтонизъм, по-едър текст и шрифтове, подходящи за дислексия, линийка за четене, маска и лупа, режим на четене, четене на глас, големи цели за щракване и сканиране с един превключвател, одит по WCAG 2.2, локални екранни снимки и запис на екрана. За Chromium, Firefox и Safari; интерфейс на 8 езика.","tags":["достъпност","разширение"]},"TurboCursa":{"line":"Псевдо-3D аркадна състезателна игра, написана на Rust: пейзажи, създавани от зърно, 11 режима, кариера в лига и 2 играчи. Оригинална; без код или ресурси от друга игра.","detail":"Clean-room псевдо-3D аркадно състезание, написано на Rust: оригинален енджин, графика, музика и име, всичко генерирано от начален параметър (19 пейзажа), кампания, състезание с времето, безкрайно, Rush Hour, слалом, огледално, Blackout, Zen, срещу компютър, екран за двама играчи и кариера с дивизии. Работи нативно или като уеб файл; интерфейс на 8 езика.","tags":["състезания","Rust"]},"ANTENA":{"line":"В разработка: решаване на жични антени, съвместимо с NEC-2 (метод на моментите), с интерфейс в браузъра. Засега само пре-алфа скелет.","detail":"В процес на разработка: решавач за жични антени, съвместим с NEC-2 (метод на моментите), с браузърен интерфейс. Засега само пре-алфа скелет.","tags":["радио","антени"]},"ARBITRU":{"line":"В разработка: универсален двигател на правила за настолни, картови, зарови и логически игри с декларативен език за правилата. Засега само пре-алфа скелет.","detail":"В процес на разработка: универсален енджин за правила на настолни игри, игри с карти, зарове и пъзели, с декларативен език за правила. Засега само пре-алфа скелет.","tags":["игри","правила"]},"ASTROLABIU":{"line":"В разработка: двигател за небесни събития на чист Rust (времеви скали, затъмнения, изгреви и залези, календари). Засега само пре-алфа скелет.","detail":"В процес на разработка: енджин за небесни събития (времеви скали, затъмнения, изгрев и залез, календари), на чист Rust. Засега само пре-алфа скелет.","tags":["астрономия","календари"]},"ECOGRAMA":{"line":"В разработка: редактор на спектрограми и реставрация на звук: избирайте на спектрограмата, поправяйте, експортирайте. Засега само пре-алфа скелет.","detail":"В процес на разработка: редактор на спектрограми и аудиореставрация: избор върху спектрограмата, поправка, експорт. Засега само пре-алфа скелет.","tags":["аудио","реставрация"]},"ecou-spectral-rs":{"line":"В разработка: роден редактор на спектрограми на Rust с приставки за намаляване на шума и засичане на звуци. Има скелет на кода и формат на приставките, но още няма завършени функции.","detail":"В процес на разработка: нативен редактор на спектрограми на Rust с плъгини за намаляване на шума и откриване на глас. Има скелет на кода и формат на плъгините, но още няма завършена функция.","tags":["аудио","Rust"]},"MARTOR":{"line":"В разработка: съдебно улавяне на уеб в WARC/WACZ с хешове, подписи и надеждни времеви печати, проверимо офлайн. Засега само пре-алфа скелет.","detail":"В процес на разработка: криминалистично улавяне на уеб в WARC/WACZ с хешове, подписи и доверени времеви печати, проверимо офлайн. Засега само пре-алфа скелет.","tags":["архивиране","доказателства"]},"NEAMURI":{"line":"В разработка: двигател за родство — от пътя в семейното дърво до правилния термин за родство на много езици. Засега само пре-алфа скелет.","detail":"В процес на разработка: енджин за родство, от пътя в родословното дърво до точния термин за роднина на много езици. Засега само пре-алфа скелет.","tags":["родство","родословие"]},"TACTIL":{"line":"В разработка: слой за осезаем изход: формати на Брайл (BRF, Unicode), дисплеи, релефни принтери и вибрация на сензорния екран. Засега само пре-алфа скелет.","detail":"В процес на разработка: слой за тактилен изход: формати за брайл (BRF, Unicode), дисплеи, принтери за релеф и вибрация на сензорен екран. Засега само пре-алфа скелет.","tags":["Брайл","достъпност"]},"atelier-verificare":{"line":"Проверявайте снимки, видео, връзки и домейни в браузъра, нищо не се качва: истински тип на файла и SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (само за четене), анализ на нивото на грешка. Не може да докаже, че снимката е истинска. Алфа.","detail":"Набор от инструменти за проверка за журналисти и внимателни читатели, който работи локално. Добавете изображения, видеа, връзки, домейни или текст и получете находки с ниво на загриженост за всяка: истинският тип файл, SHA-256, EXIF и GPS позиция, XMP и IPTC, следи от генератори на изображения с ИИ, манифести на Content Credentials (C2PA; четени, не валидирани), анализ на нивото на грешка за JPEG, метаданни на видео с ключови кадри за обратно търсене на изображения и анатомия на връзки. Две по избор мрежови проверки (обобщение на DNS, Internet Archive) се изпълняват само след като отметнете поле за съгласие. Отчетът (Markdown, JSON или PDF) изброява ограниченията на метода. Не може да докаже, че една снимка е автентична: липсата на метаданни говори малко, а метаданните могат да бъдат подправени. Алфа; девет от единайсетте проверки работят офлайн; файловете остават в браузъра.","tags":["журналистика","проверка","снимки"]},"balanta":{"line":"Сравнявайте модели на ИИ на сляпо: поставете отговорите на от два до осем модела на 92 промпта на румънски, английски и унгарски, гласувайте за A или B и получете класиране с интервали. Алфа; работи офлайн.","detail":"Слепо сравнение един до друг на ИИ модели на румънски. Вие сами поставяте отговорите на всеки модел (нищо не се извиква: без API ключове, без акаунти), приложението скрива имената на моделите в отговорите, фиксира реда от начален параметър и записва вашия глас. Класирането използва Bradley–Terry и Elo с 95% bootstrap интервали, плюс дял на победите, пристрастие към позицията и таблици „един срещу един“. Гласовете и отговорите са отворени файлове във формат JSON Lines. При малко гласове или подсказки класирането не казва нищо общо. Алфа; данните остават в браузъра; без проследяване.","tags":["ИИ","оценка"]},"calendarium":{"line":"Въведете дата в един от единадесет календара (григориански, юлиански, еврейски, хиджра, персийски, китайски, маи, марсиански…) и я вижте във всички останали, с изглед за месеца. Алфа; работи офлайн.","detail":"Преобразува дати между единайсет календара (григориански, юлиански, ревизиран юлиански, еврейски, хиджра, персийски, коптски, етиопски, китайски, на маите и Mars Sol Date), показва юлианския ден, деня от седмицата и седмицата по ISO и има месечен изглед с втори календар под всеки ден. Включва румънски бележки (стар и нов стил, преминаването през 1919 г., Великден) и атлас на календарите, по един плъгин за всеки календар. Стойностите са изчислени, с посочени ограничения (календарът на хиджра е табличният; диапазоните са защитени). Алфа, на 8 езика, работи офлайн; без проследяване.","tags":["календари","време"]},"glosar":{"line":"Офлайн речник за влашки, мегленорумънски и романи: търсете без диакритики, вижте кои основни думи липсват и добавяйте думи с източник и регистър. Алфа.","detail":"Речници за малцинствени и застрашени езици, създадени от техните носители. Търси без значение на диакритичните знаци, показва надеждност (чернова, с източник, прегледано), има таблица на покритието за 50 основни понятия и позволява добавяне на думи с източник, лиценз и запис (до 50 KB). Експортира TSV и Anki файлове и файл с принос за проекта. Началните списъци са малки — числителни и няколко думи, всяка с публикуван източник — и още никой носител на езика не ги е прегледал. Алфа; работи офлайн; данните остават в браузъра, докато не ги изтеглите.","tags":["езици","речници"]},"graiul":{"line":"Офлайн архив на румънския фолклор (поговорки, баяния, гатанки, коледарски песни) с източник, окръг и съгласие. Започва с десет поговорки; можете да добавяте още. Алфа.","detail":"Търсене без значение на диакритичните знаци, с филтри по тип, окръг и надеждност; пословица на деня (една и съща за всички в дадена дата), схематична плочкова карта на 41 окръга и Букурещ, и форма за добавяне, която изисква източник и, за заклинания и всичко събрано от човек, съгласие. Експортира файл с принос и TSV. Началните данни са десет румънски пословици от Wikiquote; никоя не е прегледана от фолклорист. Алфа; работи офлайн; данните остават в браузъра, докато не ги изтеглите.","tags":["фолклор","архив"]},"indicativ-international":{"line":"Упражнявайте въпроси от радиолюбителския изпит с график на повторение в пет кутии и пробни изпити на време; внасяйте пакети с въпроси в общ формат JSON. Включени са 50 упражнения; не е официална банка. Алфа.","detail":"Тренажор и симулатор на изпит за въпроси за радиолюбителски лиценз, с общ формат на пакетите, така че всяка държава да може да добави своя банка. „Тренировка“ повтаря верните отговори след 1, 3, 7, 14 и 30 дни и обяснява всеки отговор с неговия източник; „Изпит“ е тест с ограничено време и праг за успех; „Пакети“ внася и проверява пакети и архивира напредъка ви. Вграденият пакет съдържа 50 оригинални упражнителни въпроса, написани за този проект — не е официална банка — и засега не е включен пакет за нито една държава. Алфа; работи офлайн; напредъкът остава в браузъра.","tags":["радио","изпити"]},"proiector-fara-frontiere":{"line":"Телефоните в класната стая стават общ екран без сървър и акаунти: таймер, анкета, викторина, бележки и дъска; сдвояване с QR код или поставен текст в една и съща мрежа. Алфа: на реални телефони още не е тествано.","detail":"Споделен екран за класната стая, без сървър и без акаунт. Учителят отваря страницата при проектора; телефонът на всеки ученик се присъединява чрез обмен на код (QR кадри, снимка на кода или поставен текст), до 30 телефона едновременно. Включени са пет дейности: таймер за обратно броене, анкета с ленти на живо, викторина (въпроси от JSON, обикновен текст или CSV файл; верният отговор остава на проектора, докато не бъде разкрит; бонус за скорост и класация), лепящи бележки и бяла дъска с един цвят за всеки телефон. Резултатите могат да се запазят като CSV, текст или PNG. Всяка дейност работи в изолирана рамка само с разрешенията, които декларира, а нова дейност е един дескриптор и един скрипт. Учителят може да заключи или премахне телефон и да приключи сесията; всяко устройство избира собствен език (осем) и вид (тъмен, висок контраст, едър текст). Работи офлайн, след като бъде отворен, и може да се инсталира. Алфа: тестван в Chromium с реални връзки на една машина, не на истински телефони, други браузъри или училищни мрежи. Сдвояването изисква същата локална мрежа (без релей), показва IP адреса на всяко устройство на другото и не проверява кой е другото устройство. Форматът на викторината „Undava“ не се поддържа: не е открита спецификация.","tags":["клас","проекция","викторина"]},"regula":{"line":"Играйте пет класически игри за двама (мелница, алкерк, фанорона, му тореере, хнефатафл) срещу компютъра или приятел; добавете своя игра като JSON. Алфа; работи офлайн.","detail":"Един енджин за правила на традиционни настолни игри: всяка игра е JSON файл, а текстът на правилата на осем езика се генерира от същите данни, по които играе енджинът, така че текстът и играта не могат да си противоречат. Всяка страна може да бъде човек, случаен играч или компютърът на две нива; отмяна, връщане, подсказка и запис на ходовете, който можете да копирате. Можете да поставите, валидирате и играете собствена игра. Игрите са реконструкции, не турнирни правила, и всяка посочва колко е сигурна в правилата си. Алфа; работи офлайн; без проследяване.","tags":["игри","правила"]},"vietar-packs":{"line":"Разглеждайте, внасяйте, проверявайте и създавайте регионални пакети с видове за VietAR: имена на няколко езика, маркери за токсичност, сходни видове. Пет чернови на стартови пакети със 71 вида. Алфа; работи офлайн.","detail":"Регионални пакети с видове за VietAR: имена на няколко езика, флаг за токсичност, опасни подобни видове и място за лицензирани снимки и връзки към звуци. Разглеждайте и търсете в пет начални пакета (Румъния: растения и гъби, птици, бозайници; България и Молдова: скелети), внесете пакет, проверете го със същите правила като хранилището или създайте такъв за училищен клас или клуб на природолюбители. Началните пакети са чернови без снимки или звуци, а „не е отбелязано като токсично“ никога не означава ядливо или безопасно. Приложението VietAR още не може да внася пакети. Алфа; работи офлайн.","tags":["природа","видове"]},"PatruZeci":{"line":"Илюстриран анимиран атлас на приложенията на WD-40: ръководство със 147 карти и официален списък с 1993 приложения, всяко със собствена анимирана сцена. Неофициално, офлайн, без акаунт.","detail":"Илюстриран, анимиран атлас на приложенията на спрея WD-40 в един офлайн файл: ръководство от 147 карти в 14 категории (с ниво на риск и какво прави спреят), официалният списък „2000+ приложения“ с 1993 записа и раздел с 25 допълнителни приложения, митове и предупреждения от уеб статии. 131 анимирани варианта на сцени, филтри по категория и функция, интерфейс на 8 езика. Неофициално, независимо приложение.","tags":["WD-40","направи си сам"]},"ODISEEA":{"line":"Документален филм от около 4,5 минути за Вояджър 1 и 2 в един HTML файл: сцени, генерирани на видеокартата, експорт в 2D и 3D за VR очила, на 8 езика.","detail":"Документален филм от около 4,5 минути за сондите Voyager 1 и 2, в един HTML файл, който работи локално в браузъра, без сървър и без инсталация. Процедурни сцени, генерирани от видеокартата (WebGL): планети, сонда, ракета, антена на DSN, Златният диск, хелиосферата, Бледосиньата точка. Публични изображения на NASA/JPL и Wikimedia Commons или ваше собствено изображение за всяка сцена. Експорт в 2D, половин (1920×1080) и пълен (3840×1080) 3D side-by-side, и режим за телефон за VR очила като VR BOX; амбиентна музика, генерирана в браузъра, по избор разказ. Интерфейс, разказ, надписи и надпис за авторите на 8 езика.","tags":["Вояджър","документален филм"]},"EXIF-CURAT":{"line":"В разработка: инструмент на Rust с безопасни за паметта парсери за преглед и почистване на скрити данни във файлове (изображения, PDF, Office, видео: EXIF, GPS, XMP). Засега само пре-алфа скелет.","detail":"В процес на разработка: инструмент за преглед и премахване на скритите данни във файлове (изображения, PDF, Office, видео: EXIF, GPS, XMP), с парсери, безопасни за паметта, написан на Rust. Засега само пре-алфа скелет.","tags":["метаданни","поверителност"]},"PORUMBEL":{"line":"Автоматично пренася снимките, направени с Open Camera на телефона, в папка на компютъра, по една папка на сесия, и ги отваря в LegatorOCR. Без акаунт, без облак, без crate-ове на трети страни.","detail":"Малка програма, написана на Rust, без външни крейтове (Windows, macOS, Linux), която пренася снимките, направени с Open Camera, на вашия компютър: през Wi-Fi (страница за качване или WebDAV, с QR код), през ADB (USB или Wi-Fi) или от синхронизирана папка (Syncthing и др.). Подрежда снимките в по една папка за всяка сесия на снимане и отваря всяка завършена сесия в LegatorOCR (разделяне, изправяне, изрязване, PDF с OCR). Локален контролен панел и команда „porumbel doctor“ за диагностика; нищо не напуска вашата мрежа. Версия 0.x; лиценз MIT.","tags":["снимки","пренос"]},"colibri-companion":{"line":"Приятелско десктоп приложение за локалния двигател за извод colibri: изберете модел, който подхожда на компютъра ви, изтеглете го с един клик и чатете с него. Без акаунт, без облачна услуга.","detail":"Настолно приложение, написано на Rust, за colibri (JustVugg/colibri): намира Python и colibri, показва само моделите, които се побират в паметта на компютъра ви, изтегля ги с пауза и продължаване, стартира локалния сървър и отваря чата (отговори в поток, Markdown, запазени разговори, търсене, локални документи и инструменти MCP с одобрение при всяко извикване). Панелът „Ресурси“ показва процесора, паметта, видеокартата и отворените връзки. Windows, macOS, Linux; интерфейс на 8 езика; лиценз Apache-2.0.","tags":["локален ИИ","десктоп"]},"CartaColibri":{"line":"Локална библиотека с ИИ на двигателя Colibrì: индексира избраните от вас папки, търси мигновено и моли локален модел да обобщи, извлече данни или синтезира, винаги посочвайки изходния файл. Нищо не напуска компютъра ви.","detail":"Програма, написана на Rust, с локална страница (127.0.0.1) и команден ред. Индексира папките, които изберете (оригиналите само се четат, никога не се променят), търси в пълния текст (думи, „фрази“, префикс*, AND/OR/NOT, филтри по тип, размер, местоположение) и групира файлове. Локален модел Colibrì обобщава, извлича (таблица или JSON, „НЕ Е НАМЕРЕНО“ вместо догадки), синтезира или сравнява, винаги с цитирани източници [S1], [S2] и оценка на обосноваността. Има също малкия браузър за улавяне на уеб, MCP сървър само за четене, внос (отметки, Obsidian, Zotero, RSS) и проверка на собствения ви текст спрямо библиотеката. Без акаунт, без телеметрия; интерфейс на 8 езика; алфа версия 0.2; лиценз MIT.","tags":["локален ИИ","библиотека"]},"PolyTabletop":{"line":"240 настолни игри срещу компютъра в терминал или графичен прозорец, плюс игра за двама на една клавиатура или по мрежа. Написано на Rust; двигателят и игрите нямат външни зависимости.","detail":"Clean-room колекция от настолни игри, написана на Rust: 240 игри за игра срещу компютъра, в терминала или в графичен прозорец, плюс игра на един екран и мрежова игра за двама. Абстрактни класики, игри с карти и зарове, оригинални варианти на модерни механики под собствени имена, кооперативни игри с партньор ИИ, игри със скрити роли, парти и словесни игри; каталогът има 1200 записа, с инструментариум за ролеви игри (зарове, листове, генератор на подземия, симулатор на битки). Противник ИИ (alpha-beta, MCTS), арена ИИ срещу ИИ, записи и повторения. Интерфейс на 8 езика; версия 0.9; лиценз MIT или Apache-2.0.","tags":["настолни игри","Rust"]},"STRAJA":{"line":"Щит срещу агенти с ИИ, които четат телефона ви: показва кои приложения могат да четат известията, екрана, снимките и SMS-ите ви, предупреждава, когато ново получи достъп, и ви води до настройката, където отнемате разрешението. Без акаунт, без разрешение INTERNET.","detail":"Приложение за Android (APK) и iPhone (неподписан IPA). На Android изброява приложенията с достъп до известията, услуги за достъпност, роля на асистент и разрешения за медии и SMS, с оценка на риска за всяко приложение и за целия телефон; периодичен монитор сравнява телефона с базова линия и ви известява за всеки нов достъп. Отваря точната страница в системните настройки, за да отмените достъп, и никога не променя нищо мълчаливо. Временен достъп с напомняне и ръководство за защита с 12 точки. На iPhone няма одит (iOS скрива разрешенията на другите приложения), а само ръководството, ръчен регистър и напомняния. Не може да спре агент. Без разрешение INTERNET, без резервно копие; 8 езика; версия 1.0; лиценз MIT.","tags":["поверителност","телефон"]},"CUPLAJ":{"line":"Телефония с обща линия за потапящ театър: флот от обикновени Android телефони става частна централа през Wi-Fi на мястото; без облак, без акаунти, без реклами. Отличителната функция е «cuplaj»: общата линия на стационарните телефони от 80-те до около 2006 г.","detail":"Приложение за Android (APK) и приложение за iPhone/iPad (неподписан IPA). Организатори и актьори разговарят със зрителите през локалния Wi-Fi; един телефон (контролният) е централата. Шест телефонни епохи (1985 шайбен, 1995 с клавиатура, 2003 мобилен, 2025 смартфон, 2045 носими устройства, 2080 споделен разум), обща линия, при която двама абонати споделят една линия, реални разговори, обществено оповестяване с push-to-talk, канал зад кулисите, реплики (текст на цял екран, вибрация, звънене, светкавица, изговорен глас, фантомно обаждане) и сценарий с GO и PLAY. Без инфраструктура, по избор мрежов ключ AES-128-GCM, директни P2P разговори. Без анализи, без сървъри, без акаунти. 8 езика; версия 1.10; лиценз MIT.","tags":["потапящ театър","телефония"]},"LUSTRUM":{"line":"Върнете място на телефона си: намира ненужни файлове, дубликати, подобни снимки и остатъци от приложения и ги почиства само с ваше съгласие. Няма разрешение INTERNET, така че физически не може да изпрати нищо никъде.","detail":"Приложение за Android (Kotlin). Хранилище по тип файл, големи, стари и ненужни файлове, точни дубликати (размер, бърз отпечатък, после SHA-256), подобни снимки (перцептивно хеширане), остатъци от деинсталирани приложения, JPEG компресия, кешове, размазани и тъмни снимки, Swiper (наляво = изтриване, надясно = запазване), планирано почистване и 30-дневен кош на LUSTRUM за отмяна. Без разрешение INTERNET: нищо не напуска телефона. Без магии на ниво root: Android 11+ държи всяко обикновено приложение извън папките с данни на другите приложения. 8 езика (машинни преводи); бета версия 0.8; лиценз MIT.","tags":["чистач на телефона","Android"]},"STENOGRAMA":{"line":"Транскрипция на дълго аудио направо в браузъра с локален Whisper: един HTML файл, без акаунт, без сървър, без воден знак. Аудиото ви никога не напуска устройството; изтегля се само моделът Whisper, веднъж.","detail":"Чете MP3 и WAV на части (така че дължината не е ограничена от паметта); другите формати (M4A, OGG/Opus, MP4, FLAC) се декодират цялостно. Всеки къс се реже при пауза, за да не се разцепват думите; напредъкът се запазва, така че можете да спрете и да продължите. Редактор в страницата (щракнете върху време, за да чуете мястото), премахване на типичните „призрачни“ фрази на Whisper, експорт в .txt, .srt, .vtt, .docx или в клипборда. Използва WebGPU, когато е налично, иначе процесора (WASM). Инсталируем PWA; моделът остава в кеша след първото изтегляне. Библиотеката се зарежда от jsDelivr при първата транскрипция, проверена със SHA-384. Интерфейс на 7 езика; лиценз MIT.","tags":["транскрипция","аудио"]},"GERMEN":{"line":"Обучете малък езиков модел от нулата на чист Rust на обикновен процесор: без Python, без CUDA, без акаунт, без достъп до мрежа, без телеметрия. Един двоичен файл, един текстов файл, една команда.","detail":"Програма на Rust (върху Burn, с неговия чист Rust процесорен бекенд), която обучава мрежа в стила на GPT върху байтове или върху BPE речник, научен от вашия собствен текст, след което генерира текст от обучения модел. GERMEN Studio: локален прозорец (127.0.0.1) с кривата на загубата, скоростта и примери за текст, на 8 езика. Команди за измерване на скоростта на компютъра ви и за проверка и поправка на файлове с модели. Това е работилница за учене и експериментиране, не фабрика за чатботове: модел от 1–25 милиона параметъра научава формата на един текст, не знания за света. Без GPU, без смесена точност. Версия 0.6; лиценз MIT.","tags":["локален ИИ","Rust"]},"CUANTOR":{"line":"Симулатор на квантов компютър за вашия десктоп, от 5 до 1000 кубита, с интерфейс в стил IBM Quantum Composer. Точна математика, но не истински квантов хардуер.","detail":"Програма на Rust от четири части (ядро, прозорец, команден ред, връзка с IBM) за Windows, macOS и Linux. Чертожна дъска като Composer на IBM: поставяте цветни гейтове върху линии (кубити) и наблюдавате как ленти и сфера показват резултата, докато текстов панел записва същата схема на живо в OpenQASM и Qiskit. Три калкулатора: един, който помни всяко число (до 28 кубита), един много бърз за прости гейтове (до 4096) и един за схеми с малко разклонения. Измерване, нулиране и if по средата на изпълнение, собствени гейтове, симулиран шум, повторяеми резултати с начален параметър. Чете OpenQASM 2.0 и 3.0; можете да отворите схемата в IBM Composer или да я изпратите към истинска машина на IBM със собствен ключ на акаунта си (не е проверено на реален хардуер на IBM). Интерфейс на 8 езика; версия 0.2.","tags":["квантов компютър","симулатор"]},"ERATA":{"line":"Коректор в браузъра, който проверява правопис, граматика, пунктуация и типография директно на вашия компютър: без акаунт, без сървър, без телеметрия. Най-задълбочен за румънски.","detail":"Разширение за Chromium и Firefox (версията за Safari не е тествана), написано от нулата, без код, правила или данни от LanguageTool или от друг проверяващ инструмент. Работи в полета textarea, input и contenteditable и чертае подчертаванията си, без да променя страницата. Разпознава езика за всеки абзац, възстановява диакритичните знаци (ro, fr, es, pt) само когато поправката е еднозначна и има задълбочени правила за румънски (ș/ț със запетая отдолу, „să/sa“, „într-un“, запетаята пред „dar/însă“). Личен речник, собствени правила, превключвател за всеки сайт, внасяне на речници на Hunspell. По избор преписване чрез локален модел (само localhost, изключено по подразбиране). Интерфейс на 25 езика. Версия 0.4; лиценз MIT.","tags":["коректор","разширение"]}});
